def gen(rng):
    def fmt(a, t):
        return f"{len(a)}\n{' '.join(map(str, a))}\n{t}"
    def ev(a, ops):
        total = 0
        sign = 1
        cur = a[0]
        for k, op in enumerate(ops):
            x = a[k + 1]
            if op in '+-':
                total += sign * cur
                sign = 1 if op == '+' else -1
                cur = x
            elif op == '*':
                cur *= x
            else:
                if x == 0 or cur % x != 0:
                    return None
                cur //= x
        return total + sign * cur
    tests = [
        fmt([4, 2, 3], 11), fmt([1, 1, 1], 1), fmt([1, 2, 3], 124), fmt([2, 5, 7, 3], -7),
        fmt([5], 5), fmt([5], 6), fmt([0], 0), fmt([0, 0], 0), fmt([7, 0], 7), fmt([0, 3], 0),
        fmt([6, 3], 2), fmt([6, 4], 1), fmt([8, 4, 2], 1), fmt([10, 5, 2], 0),
        fmt([1, 1, 1, 1, 1, 1], 6), fmt([9, 9, 9], 81), fmt([3, 8], -5),
    ]
    for _ in range(45):
        n = rng.randint(2, 7)
        a = [rng.randint(0, 9) for _ in range(n)]
        if rng.random() < 0.7:
            while True:
                ops = [rng.choice('*+-/') for _ in range(n - 1)]
                v = ev(a, ops)
                if v is not None:
                    break
                if rng.random() < 0.2:
                    v = rng.randint(-30, 100)
                    break
            tests.append(fmt(a, v))
        else:
            tests.append(fmt(a, rng.randint(-40, 120)))
    # max-size: n = 10
    tests.append(fmt([rng.randint(1, 99) for _ in range(10)], 10**18))
    tests.append(fmt([rng.randint(1, 9) for _ in range(10)], 123456789))
    tests.append(fmt([99] * 10, 99 ** 9))
    a = [rng.randint(1, 99) for _ in range(10)]
    while True:
        ops = [rng.choice('+-*/') for _ in range(9)]
        v = ev(a, ops)
        if v is not None:
            break
    tests.append(fmt(a, v))
    tests.append(fmt([rng.randint(1, 12) for _ in range(10)], -(10 ** 18)))
    return tests

